package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenDecimalDivisorScopeTest {
 private static final String SYSTEM="na-nied-primary-2024-v1";
 private static Question q(String prompt){return new Question("decimalDiv",prompt,"private","999");}
 @Test public void ExistingNaSevenMappingUsesPublicFiniteAndDeclaredPrecisionNotStoredValues(){
  CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,"decimalDiv",7);assertTrue(limits.decimalDivisorQuotients());assertTrue(limits.decimalDirectAnswers());assertTrue(GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(SYSTEM)).findFirst().orElseThrow().inGrade("decimalDiv",7));
  for(String prompt:List.of("3.24 ÷ 0.8","0.001 ÷ 6.4","0.000 ÷ 0.3","100.001 ÷ 0.1","12.345 ÷ 2.0")){Question q=q(prompt);q.expression=null;q.answers=null;assertTrue(prompt,limits.allows(q));assertNull(q.expression);assertNull(q.answers);assertNotNull(HelpPlan.forQuestion(q));}
  for(String prompt:List.of("3.24 ÷ 0.7","1.2345 ÷ 0.5","1.2 ÷ 0.25","1 ÷ 0")){assertFalse(prompt,limits.allows(q(prompt)));if(!prompt.endsWith(" 0"))assertTrue(prompt,CurriculumLimits.NONE.allows(q(prompt)));}
  assertFalse(new CurriculumLimits("decimalDivisorQuotients=true").allows(q("1 ÷ 3")));assertTrue(new CurriculumLimits("decimalDivisorQuotients=false").allows(q("1 ÷ 3")));assertTrue(limits.allows(q("0.001 ÷ 6.4")));assertFalse(new CurriculumLimits("answerDecimalPlaces=3").allows(q("0.001 ÷ 6.4")));
 }
 @Test public void NormalNaSevenFreshTypedSupplyUsesOriginalDividendsOnePlaceDivisorsAndFiniteSevenSteps(){
  CurriculumLimits limits=GlobalCurriculum.limits(SYSTEM,"decimalDiv",7);Generator typed=new Generator(new Random(368)),mc=new Generator(new Random(368));List<String> recent=new ArrayList<>();Set<Integer> scales=new HashSet<>();boolean twoDigit=false;
  for(int i=0;i<240;i++){Question q=typed.next("decimalDiv",recent,false,limits),other=mc.next("decimalDiv",recent,true,limits);assertEquals(q.signature(),other.signature());assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=DecimalDivisorQuotients.readGeneral(q);assertNotNull(v);assertTrue(v.left().compareTo(BigDecimal.TEN)<0);assertTrue(v.left().scale()>=1&&v.left().scale()<=3);scales.add(v.left().scale());assertEquals(1,v.right().scale());assertTrue(v.right().compareTo(new BigDecimal("0.1"))>=0&&v.right().compareTo(new BigDecimal("9.9"))<=0);twoDigit|=v.right().movePointRight(1).compareTo(BigDecimal.TEN)>=0;assertTrue(v.finitePossible());assertTrue(limits.allows(q));assertEquals("number",other.kind);assertTrue(other.choices.isEmpty());assertEquals(-1,other.correctChoice);assertEquals("decimalValue",q.answerFormat);assertTrue(new Checker().check(q,List.of(),List.of(v.left().divide(v.right()).toPlainString())).correct());assertTrue("Canonical arithmetic FULL permission must remain",q.stepSupport);assertTrue(new Checker().check(q,List.of(q.expression+"="+v.value().toString()),List.of(v.left().divide(v.right()).toPlainString()),List.of(Checker.StepKind.FULL)).correct());assertNotNull(q.studyGuide);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(7,h.size());assertEquals("decimal-arithmetic-relations-v1",h.restore(null,q.id).teachingVersion);assertFalse(h.canTransfer());}
  assertEquals(Set.of(1,2,3),scales);assertTrue(twoDigit);Question zero=DecimalDivisorQuotients.make("0.000","0.3");assertTrue(limits.allows(zero));assertTrue(new Checker().check(zero,List.of(),List.of("0")).correct());
 }
 @Test public void GeneralLimitsFilterPublicSourceResultAndBothOperandsWithoutPrivateFallback(){
  assertTrue(new CurriculumLimits("decimalPlaces=4;secondDecimalPlaces=2").allows(q("1.2345 ÷ 0.25")));assertFalse(new CurriculumLimits("decimalPlaces=3;secondDecimalPlaces=2").allows(q("1.2345 ÷ 0.25")));assertTrue(new CurriculumLimits("decimalPlaces=1;secondDecimalPlaces=4").allows(q("1.2 ÷ 0.1250")));assertFalse(new CurriculumLimits("wholeDigits=1").allows(q("1.2 ÷ 12.0")));assertTrue(new CurriculumLimits("wholeDigits=1;secondDigits=2").allows(q("1.2 ÷ 12.0")));assertFalse(new CurriculumLimits("secondDigits=1").allows(q("1.2 ÷ 12.0")));assertFalse(new CurriculumLimits("wholeMaximum=9").allows(q("12.0 ÷ 2.0")));assertFalse(new CurriculumLimits("maxGiven=0.9").allows(q("1.2 ÷ 0.5")));assertFalse(new CurriculumLimits("minGiven=0.6").allows(q("1.2 ÷ 0.5")));assertFalse(new CurriculumLimits("maxSecondOperand=1").allows(q("1.2 ÷ 1.5")));assertTrue(new CurriculumLimits("maxResult=2.4").allows(q("1.2 ÷ 0.5")));assertFalse(new CurriculumLimits("maxResult=2.399").allows(q("1.2 ÷ 0.5")));assertFalse(new CurriculumLimits("answerDomain=integer").allows(q("1.2 ÷ 0.5")));assertTrue(new CurriculumLimits("integerSecondOperand=true").allows(q("1.2 ÷ 2.0")));assertFalse(new CurriculumLimits("integerSecondOperand=true").allows(q("1.2 ÷ 2.1")));for(String control:List.of("denominators=2","sameDecimalPlaces=true","wholeDecimalQuotients=true","wholeDivisorMaximum=99","includeWholeDecimalProducts=true"))assertFalse(control,new CurriculumLimits(control).allows(q("1.2 ÷ 0.5")));try{new CurriculumLimits("decimalDivisorQuotients=unknown");fail("Invalid scoped flag accepted");}catch(IllegalArgumentException expected){}
 }
 @Test public void OldUnselectedGeneratorRandomSignaturesChoicesAndOtherDecimalTopicsRemain(){
  Random prior=new Random(3681);Generator current=new Generator(new Random(3681));Catalog.Skill legacy=Catalog.get("decimalDiv");for(int i=0;i<60;i++){prior.nextInt(Math.max(legacy.range,2));prior.nextInt(Math.max(Math.min(legacy.range,12),2));prior.nextInt(9);prior.nextInt(989);Rational y=Rational.of(11+prior.nextInt(89),10),x=y.mul(Rational.of(1+prior.nextInt(99),10));Question q=current.create(Catalog.get("decimalDiv"));assertEquals(x.decimalText()+" / "+y.decimalText(),q.prompt);assertEquals(x.div(y),DecimalDivisorQuotients.value(q));assertFalse(DecimalDivisorQuotients.selected("decimalDiv",CurriculumLimits.NONE));assertEquals(7,HelpPlan.forQuestion(q).size());}
  boolean foundChoices=false;for(int seed=0;seed<40;seed++){Question q=new Generator(new Random(seed)).next("decimalDiv",List.of(),true,CurriculumLimits.NONE);if(!q.choices.isEmpty()){foundChoices=true;assertTrue(q.correctChoice>=0);assertTrue(new Checker().check(q,List.of(),List.of(q.choices.get(q.correctChoice))).correct());}}assertTrue(foundChoices);assertFalse(GlobalCurriculum.limits(SYSTEM,"decimalDivInt",6).decimalDivisorQuotients());assertFalse(GlobalCurriculum.limits("england-primary-2021-v1","decimalDiv",6).decimalDivisorQuotients());assertTrue(GlobalCurriculum.limits("ke-kicd-cbc-2024-v1","decimalDiv",7).allows(q("1.2345 ÷ 0.2")));assertEquals(9,HelpPlan.forQuestion(new Question("decimalMul","4.15 × 0.2","poison","999")).size());assertEquals(9,HelpPlan.forQuestion(DecimalWholeQuotients.make("3.375",13)).size());
 }
}
